export function getAudioAsset(text: string): string | undefined {
  const t = text.trim();
  if (manifest[t]) return manifest[t];
  if (t.startsWith("ال") && manifest[t.slice(2)]) return manifest[t.slice(2)];
  return undefined;
}

export const audioAssetCount = Object.keys(manifest).length;
